output_text:
[
  {
    "id": "take_cart_from_entrance",
    "text": "A shopper is obliged to take the shopping cart from the entrance cart station before continuing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "cart_available_at_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "acquire_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "cartAt(1,5)",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "acquire_entrance_cart"
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "Required shelf items may only be picked up while the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "hand_pickup_attempt": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_pickup_attempt"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers are prohibited from carrying groceries by hand rather than placing them in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {
        "becomes_hand_full": {
          "pre": {
            "not": "handFull"
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_to_0_1",
    "text": "After taking a cart, the shopper is obliged to return it to the cart-return point at cell (0,1) before leaving.",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_at_0_1": {
          "pre": {
            "and": [
              "hasCart",
              "cart_return_point",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "cartAt(0,1)",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_at_0_1"
    }
  },
  {
    "id": "do_not_abandon_cart_elsewhere",
    "text": "A cart may not be left anywhere except the designated cart-return point at (0,1).",
    "abstraction": {
      "state_properties": {
        "designated_cart_return": "at(0,1)",
        "not_at_designated_return": {
          "not": "designated_cart_return"
        }
      },
      "events": {
        "leave_cart_outside_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_designated_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return"
    }
  },
  {
    "id": "exit_without_cart",
    "text": "Shoppers are prohibited from exiting the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "at_store_exit": "at(9,5)",
        "cart_in_possession": "hasCart"
      },
      "events": {
        "cart_exit_attempt": {
          "pre": {
            "and": [
              "EXIT",
              "cart_in_possession"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_exit_attempt"
    }
  },
  {
    "id": "after_item_return_loaded_cart",
    "text": "Once any item has been collected into a cart, the loaded cart must eventually be parked at the return point.",
    "abstraction": {
      "state_properties": {
        "loaded_cart_context": "hasCart",
        "cart_return_cell": "at(0,1)"
      },
      "events": {
        "collect_item_with_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "loaded_cart_context"
            ]
          },
          "post": "hasCart"
        },
        "park_loaded_cart": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "cart_return_cell",
              "hasCart"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collect_item_with_cart",
      "discharge": "park_loaded_cart"
    }
  },
  {
    "id": "do_not_retake_returned_cart",
    "text": "After a cart has been parked at the return point, it may not be picked up again.",
    "abstraction": {
      "state_properties": {
        "returned_cart_present": {
          "and": [
            "at(0,1)",
            "cartAt(0,1)"
          ]
        }
      },
      "events": {
        "retake_returned_cart": {
          "pre": {
            "and": [
              "returned_cart_present",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "retake_returned_cart"
    }
  }
]
